<template>
  <div class="wrapper">
    <div class="container">
      <div class="box">
        <div class="up">
          <p class="title">手机号码登录</p>
          <ul class="form">
            <li>
              <input type="text" v-model="userId" placeholder="手机号码" />
            </li>
            <li>
              <input type="password" v-model="password" placeholder="密码" />
            </li>
          </ul>
          <div class="error" v-if="isError">
            <i class="fa fa-exclamation"></i>
            <p>{{ errorMsg }}</p>
          </div>
        </div>
        <div class="down">
          <div class="button-login">
            <button @click="login">登 录</button>
          </div>
          <div class="tnc">
            <input type="checkbox" id="checkbox" class="checkbox" />
            <p class="text">
              阅读并同意旅客之家的<span class="highlight">服务协议</span>
            </p>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "UserLogin",
  data() {
    return {
      userId: "",
      password: "",
      isError: false,
      errorMsg: "",
      prePath: "", //previous page url
    };
  },
  // invoked before this page instances are created
  // next() allow page to continue create instance
  beforeRouteEnter(to, from, next) {
    next((thisPage) => {
      thisPage.prePath = from.path; //get previous page url
    });
  },
  methods: {
    // login user
    login() {
      this.isError = false;
      //console.log(this.prePath);
      // show error message
      this.errorMsg = "";
      if (this.userId == "") {
        this.isError = true;
        this.errorMsg = "请输入手机号码";
        return;
      }
      if (this.password == "") {
        this.isError = true;
        this.errorMsg = "请输入密码";
        return;
      }
      if (!document.getElementById("checkbox").checked) {
        this.isError = true;
        this.errorMsg = "请阅读并同意旅客之家的服务协议";
        return;
      }

      // get user id from backend
      this.$axios
        .get(`UserController/getUserByIdPass/${this.userId}/${this.password}`)
        .then((response) => {
          let user = response.data.result;

          if (user == null) {
            this.isError = true;
            this.errorMsg = "用户名或密码不正确";
            console.log("Login failed");
            // reset input
            this.userId = "";
            this.password = "";
            return;
          }

          this.$setSessionStorage("user", user);
          console.log("Login success");

          // go to admin page
          if (user.isAdmin) {
            this.$router.push({ path: "/admin", replace: true });
          } else {
            // if user come from register/profile page, redirect to index
            if (
              this.prePath == "/user/register" ||
              this.prePath == "/user/profile" ||
              this.prePath == "/admin"
            ) {
              this.$router.push({
                path: "/index",
                replace: true, //replace current history instead of adding, so back to /login is not possible
              });
            } else {
              this.$router.go(-1);
            }
          }
        })
        .catch((error) => {
          console.error(error);
        });
    },
  },
};
</script>

<style scoped>
.wrapper {
  height: 100%;
  width: 100%;
}

/*************** login box *****************/
.wrapper .container {
  display: flex;
  justify-content: center;
  margin: 3vw;
  padding-bottom: 3vw;
}

.wrapper .container .box {
  height: 100%;
  width: 30vw;
  border-radius: 1vw;
  box-shadow: 3px 3px 3px #c3c3c3;
  border: 1px solid #c3c3c3;
  box-sizing: border-box;
  padding: 2vw;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.wrapper .container .box .title {
  font-size: 1.5vw;
}

/*************** form box *****************/
.wrapper .container .box .form {
  width: 100%;
  padding-top: 1vw;
}

.wrapper .container .box .form li {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  padding: 1vw 0 0;
}

.wrapper .container .box .form li input {
  width: 100%;
  box-sizing: border-box;
  padding: 1.5vw 1vw;
  border-radius: 0.5vw;

  font-size: 1vw;
  border: 1px solid #c3c3c3;
  outline: none;
}

/*************** error msg *****************/
.wrapper .container .box .error {
  display: flex;
  align-items: center;
  margin: 1vw 0 0;
  padding: 0 1vw;
  height: 2vw;
  background-color: var(--color-orange2);
  border: 1px solid var(--color-orange);
  border-radius: 0.5vw;
  color: var(--color-orange);
  font-weight: normal;
  font-size: 1vw;
}
.wrapper .container .box .error i {
  display: flex;
  justify-content: center;
  width: 1vw;
  margin-right: 0.5vw;
  font-size: 1vw;
  padding: 0.1vw;
  background-color: var(--color-orange);
  color: white;
  border-radius: 5vw;
}

/*************** login button *****************/
.wrapper .container .box .button-login {
  width: 100%;
  padding: 2vw 0 1vw;
}

.wrapper .container .box .button-login button {
  width: 100%;
  height: 4vw;
  background-color: var(--color-orange);
  border: none;
  outline: none;
  border-radius: 0.5vw;

  font-size: 1.5vw;
  font-weight: bold;
  color: white;

  cursor: pointer;
  position: relative;
  overflow: hidden;
  z-index: 1;
}

/*************** tnc button *****************/
.wrapper .container .box .tnc {
  display: flex;
  align-items: center;
}
.wrapper .container .box .tnc .checkbox {
  cursor: pointer;
  width: 1vw;
  margin: 0 0.5vw 0 0;
}
.wrapper .container .box .tnc .text {
  font-size: 1vw;
  font-weight: normal;
  color: var(--color-text);
}
.wrapper .container .box .tnc .text .highlight {
  color: var(--color-text2);
  cursor: pointer;
}

/*************** login button animation *****************/
.wrapper .container .box .button-login button::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  transform: translateX(-100%);
  transition: transform 0.2s ease-in-out;
  height: 100%;
  width: 100%;
  background-color: #d94500;
  z-index: -1;
}

.wrapper .container .box .button-login button:hover::before {
  transform: translateX(0);
}

/*************** register button animation *****************/
.wrapper .register::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0%;
  transform: translateX(-100%) translateY(100%) scale(0);
  transition: transform 0.3s ease-in-out;
  height: 0.1vw;
  width: 100%;
  border-radius: 2px;
  background-color: var(--color-blue1);
}

.wrapper .register:hover::before {
  transform: translateX(0%) translateY(100%);
}
</style>
